export function getSurah(number) {
  return surahs.find((surah) => surah.number === Number(number)) ?? surahs[0]
}

export function getJuz(number) {
  return juzs.find((juz) => juz.number === Number(number)) ?? juzs[0]
}

export function getRandomSurah() {
  const randomIndex = Math.floor(Math.random() * surahs.length)
  return surahs[randomIndex]
}
